 'c4:granVisit':()=>[ say('gran',"A journey to the Five Peaks takes good packing. Warm socks. Sunleaf tea. And your very best writing hand.",sc('room',[['gran',300,270,1,{expr:'happy'}],['nora',700,250,1,{arm:'hold'}]])) ],
 'c4:pack':()=>[ say(null,"Grandma unrolls an old map. The names on it are so faded you can hardly see them. Can you spell them again, Lucas? she asks.",sc('office',[['gran',300,270,1,{}],['nora',700,250,1,{expr:'wow'}]])) ],
 'c4:oldMap':()=>[ say(null,"Now Lucas knows the way. All they need is something big enough to fly them over the clouds.",sc('field',[['nora',512,250,1.05,{expr:'wow'}]])) ],
